-- Issue #176: the crate Favor guide (web/site/lib/crateFavorGuide.ts) is bundled in the addon as
-- CraftWise/Data/CrateFavorGuide.lua, generated by tools/gen_crate_favor_guide.lua. This spec fails when the
-- TypeScript changes and the Lua file wasn't regenerated (`lua5.1 tools/gen_crate_favor_guide.lua`), and tests
-- the order: measured, tooltip, guide.
local G = dofile("tools/gen_crate_favor_guide.lua")

local function Read(path)
	local f = io.open(path, "rb")
	if not f then
		return nil
	end
	local text = f:read("*a")
	f:close()
	return text
end

it("#176: the committed CrateFavorGuide.lua matches what the generator writes now", function()
	local saved = Read(G.OUT)
	assert(saved, G.OUT .. " missing: run lua5.1 tools/gen_crate_favor_guide.lua")
	assert(saved:gsub("\r\n", "\n") == G.Build(), G.OUT .. " is out of date: run lua5.1 tools/gen_crate_favor_guide.lua")
end)

it("#176: the generated file keeps the source header, both sources and the values", function()
	local text = G.Build()
	for _, needle in ipairs({
		"Third-party values from the WoW: Forever",
		"https://forevermastery.com/en/guides/wow-forever-merchants-favor", "https://foreverchanges.pro/merchants-favor",
		"do not edit", "Apprentice = {", "Expert = {", "Herbs = { 15, \"rule\" }", "Fabrics = { 30, \"listed\" }",
	}) do
		assert(text:find(needle, 1, true), needle)
	end
	assert(not text:find("Artisan = {", 1, true), "Artisan has no value")
end)

local HERBS = 248682

it("#176: guide Favor is used only without a measured or tooltip reward; measured and tooltip win", function()
	local ns, stub = LoadAddon({ auctionator = true })
	assert(loadfile(G.OUT))("CraftWise", ns)
	local Cr = ns.Crates
	local g, basis = Cr.GuideFavor("Waylaid Crate: Apprentice Herbs")
	eq(g, 5); eq(basis, "listed")
	eq(Cr.GuideFavor("Waylaid Crate: Earthly Expert Herbs"), 15)
	eq(Cr.GuideFavor("Waylaid Crate: Artisan Herbs"), nil)
	eq(Cr.GuideFavor("Linen Cloth"), nil)
	eq(Cr.GuideFavor(nil), nil)
	ns.db.crates = ns.db.crates or {}
	ns.db.crates[HERBS] = { name = "Waylaid Crate: Apprentice Herbs", fill = {}, got = {} }
	local n, from = Cr.Reward(HERBS)
	eq(n, 5); eq(from, "guide")
	ns.db.crates[HERBS].got = { { n = 7 }, { n = 7 } }
	n, from = Cr.Reward(HERBS)
	eq(n, 7); eq(from, "seen")
	ns.db.crates[HERBS].reward = 9
	n, from = Cr.Reward(HERBS)
	eq(n, 9); eq(from, "tooltip")
end)
